<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue';
import CloudToolsNav from './CloudToolsNav.vue';
import WorkspaceSidebar from './WorkspaceSidebar.vue';
import CloudHistoryRuns from './CloudHistoryRuns.vue';
import CloudHistoryEvents from './CloudHistoryEvents.vue';
import CloudHistoryExport from './CloudHistoryExport.vue';
import {historySources,historyStatuses,reasonLabels,historyCount,type HistorySource,type HistoryRun} from './cloud-history-types';
import {readHistoryRoute,validateHistoryRoute,historyRouteURL,emptyHistoryFilters,coverageLabels,historyRequestKey,type HistoryRoute} from './cloud-history-route';
const initial=readHistoryRoute(location.search),route=ref<HistoryRoute>(initial.route),routeError=ref(initial.error),formError=ref(''),draft=ref({...initial.route.filters}),pageStack=ref<string[]>([]),eventStack=ref<string[]>([]),loadedPage=ref<{rows:HistoryRun[];context:string;observedAt:string}|null>(null),auth=ref(false),sidebarError=ref('');
const selectedSummary=computed(()=>{const page=loadedPage.value;if(!page||page.context!==historyRequestKey(route.value))return null;const record=page.rows.find(row=>row.source===route.value.source&&row.run_id===route.value.run);return record?{record,observedAt:page.observedAt}:null;});
function openRun(row:HistoryRun){if(auth.value||row.source!==route.value.source)return;eventStack.value=[];commit({...route.value,run:row.run_id,eventBefore:'0'});}
function closeRun(){eventStack.value=[];commit({...route.value,run:'',eventBefore:'0'});}
function nextEvents(before:string){if(auth.value||!historyCount(before,false))return;eventStack.value.push(route.value.eventBefore);commit({...route.value,eventBefore:before});}
function previousEvents(){if(auth.value)return;commit({...route.value,eventBefore:eventStack.value.pop()||'0'});}
function requireLogin(){if(auth.value)return;auth.value=true;location.assign('/login?next='+encodeURIComponent('/cloud/history'+location.search));}
function commit(value:HistoryRoute){const error=validateHistoryRoute(value);if(error){formError.value=error;return;}routeError.value='';formError.value='';route.value=value;draft.value={...value.filters};const url=historyRouteURL(value);if(location.pathname+location.search!==url)history.pushState(null,'',url);}
function apply(){const value={...route.value,filters:{...draft.value},before:'0',run:'',eventBefore:'0'};if(validateHistoryRoute(value)){formError.value=validateHistoryRoute(value);return;}pageStack.value=[];commit(value);}
function clear(){pageStack.value=[];commit({source:route.value.source,filters:emptyHistoryFilters(),before:'0',run:'',eventBefore:'0'});}
function changeSource(event:Event){const source=(event.target as HTMLSelectElement).value as HistorySource;pageStack.value=[];commit({source,filters:{...route.value.filters,coverage:'',reason:'',min:'',max:''},before:'0',run:'',eventBefore:'0'});}
function next(before:string){if(auth.value||!historyCount(before,false))return;pageStack.value.push(route.value.before);commit({...route.value,before,run:'',eventBefore:'0'});}
function previous(){if(auth.value)return;commit({...route.value,before:pageStack.value.pop()||'0',run:'',eventBefore:'0'});}
function pop(){const parsed=readHistoryRoute(location.search);route.value=parsed.route;routeError.value=parsed.error;formError.value='';draft.value={...parsed.route.filters};pageStack.value=[];eventStack.value=[];}
onMounted(()=>{document.title='扫描历史 · NAS Downloader';window.addEventListener('popstate',pop);});onUnmounted(()=>window.removeEventListener('popstate',pop));
</script>
<template><div class="workspace event-workspace cloud-history-workspace"><WorkspaceSidebar active="/cloud/history" @error="sidebarError=$event"/><main class="main"><header class="page-header"><div><p class="eyebrow">本地运行与审计</p><h1>扫描历史</h1><p class="muted">统一查看三类扫描的持久记录。读取历史不会启动扫描或请求百度目录。</p></div></header><CloudToolsNav active="/cloud/history"/><p v-if="sidebarError" class="notice danger" role="alert">{{sidebarError}}</p><label>历史类型<select :value="route.source" data-testid="history-source" :disabled="auth" @change="changeSource"><option v-for="(name,key) in historySources" :key="key" :value="key">{{name}}</option></select></label><form class="event-filter-panel history-filters" @submit.prevent="apply"><label>运行状态<select v-model="draft.status" :disabled="auth"><option value="">全部状态</option><option v-for="(name,key) in historyStatuses" :key="key" :value="key">{{name}}</option></select></label><label>开始于 UTC 日期<input v-model="draft.from" type="date" :disabled="auth"/></label><label>截至 UTC 日期（含）<input v-model="draft.to" type="date" :disabled="auth"/></label><template v-if="route.source==='scan'"><label>当时覆盖状态<select v-model="draft.coverage" :disabled="auth"><option value="">全部覆盖状态</option><option v-for="(name,key) in coverageLabels" :key="key" :value="key">{{name}}</option></select></label><label>当时覆盖原因<select v-model="draft.reason" :disabled="auth"><option value="">全部原因</option><option value="unrecorded">历史未记录</option><option v-for="(name,key) in reasonLabels" :key="key" :value="key">{{name}}</option></select></label><label>未完整目录最少<input v-model="draft.min" inputmode="numeric" :disabled="auth"/></label><label>未完整目录最多<input v-model="draft.max" inputmode="numeric" :disabled="auth"/></label></template><div class="history-filter-actions"><button class="button primary" data-testid="history-apply" :disabled="auth">应用筛选</button><button class="button secondary" type="button" :disabled="auth" @click="clear">清除条件</button></div></form><p v-if="routeError||formError" class="notice danger" role="alert">{{routeError||formError}}</p><CloudHistoryExport v-if="!routeError" :source="route.source" :filters="route.filters" :disabled="auth" @authentication-required="requireLogin"/><CloudHistoryRuns v-if="!routeError" :route="route" :disabled="auth" :previous-label="pageStack.length?'上一批':'回到首批'" @authentication-required="requireLogin" @next="next" @previous="previous" @open="openRun" @loaded="loadedPage=$event"/><CloudHistoryEvents v-if="!routeError&&route.run" :key="route.source+':'+route.run" :source="route.source" :run="route.run" :before="route.eventBefore" :summary="selectedSummary" :disabled="auth" :previous-label="eventStack.length?'较新事件':'回到最新事件'" @close="closeRun" @next="nextEvents" @previous="previousEvents" @authentication-required="requireLogin"/></main></div></template>
<style scoped>.cloud-history-workspace :deep(th){width:auto}.cloud-history-workspace :deep(.muted){overflow-wrap:anywhere}.cloud-history-workspace select,.cloud-history-workspace input{font:inherit;padding:9px 12px;border:1px solid #dfe3ed;border-radius:8px;background:white;max-width:100%}.cloud-history-workspace>main>label{display:block;margin:16px 0}.history-filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px}.history-filters label{display:grid;gap:8px}.history-filter-actions{grid-column:1/-1;display:flex;flex-wrap:wrap;gap:12px}</style>
